 <script>
    document.addEventListener('DOMContentLoaded', function () {
      const menu = document.querySelector('.menu');
      document.querySelectorAll('.has-sub > a').forEach(link => {
        link.addEventListener('click', function (e) {
          e.preventDefault();
          e.stopPropagation();

          const parentLi = this.parentElement;
          // Find the closest container that holds all the lists at this level
          const subMenuContainer = parentLi.closest('.submenu') || menu;

          // 1. Find ALL active items within this specific submenu level
          // but NOT the one we just clicked
          subMenuContainer.querySelectorAll('.has-sub.active').forEach(item => {
            // Only close if it's not the current item or a parent of the current item
            if (item !== parentLi && !item.contains(parentLi)) {
              item.classList.remove('active');

              // Also close any deeper nested menus inside the one we're closing
              item.querySelectorAll('.has-sub.active').forEach(child => {
                child.classList.remove('active');
              });
            }
          });

          // 2. Toggle the clicked item
          parentLi.classList.toggle('active');
          toggleBodyFreeze();
        });
      });

      // Close everything when clicking outside
      document.addEventListener('click', function (e) {
        if (menu && !menu.contains(e.target)) {
          document.querySelectorAll('.has-sub.active').forEach(item => {
            item.classList.remove('active');
          });
          toggleBodyFreeze();
        }
      });
    });


    function toggleBodyFreeze() {
    const hasActive = document.querySelector('.has-sub.active');
    
    if (hasActive) {
        document.body.classList.add('all_background_freeze');
    } else {
        document.body.classList.remove('all_background_freeze');
    }
}
  </script>

